import React, { useEffect, useState } from 'react'
import { Clock, Plus, Trash2 } from 'lucide-react'

export interface TimeRange {
  start: string
  end: string
}

interface TimeRangePickerProps {
  ranges: TimeRange[]
  onChange: (ranges: TimeRange[]) => void
}

export const calculateDuration = (ranges: TimeRange[]): string => {
  let totalMinutes = 0

  ranges.forEach(({ start: startStr, end: endStr }) => {
    if (!startStr || !endStr) return
    
    const start = new Date(`2000-01-01T${startStr}`)
    const end = new Date(`2000-01-01T${endStr}`)
    
    if (isNaN(start.getTime()) || isNaN(end.getTime())) return

    if (end < start) {
      end.setDate(end.getDate() + 1)
    }

    const diffMs = end.getTime() - start.getTime()
    totalMinutes += Math.floor(diffMs / 60000)
  })

  const hours = Math.floor(totalMinutes / 60)
  const mins = totalMinutes % 60
  
  if (hours === 0 && mins === 0) return ''
  return `${hours}h${mins}m`
}

export const TimeRangePicker: React.FC<TimeRangePickerProps> = ({
  ranges,
  onChange,
}) => {
  const [duration, setDuration] = useState('')

  useEffect(() => {
    setDuration(calculateDuration(ranges))
  }, [ranges])

  const handleAddTimeRange = () => {
    onChange([...ranges, { start: '', end: '' }])
  }

  const handleRemoveTimeRange = (index: number) => {
    const newRanges = ranges.filter((_, i) => i !== index)
    onChange(newRanges)
  }

  const handleTimeChange = (index: number, field: 'start' | 'end', value: string) => {
    const newRanges = [...ranges]
    newRanges[index] = { ...newRanges[index], [field]: value }
    onChange(newRanges)
  }

  return (
    <div className="flex flex-col gap-2">
      <label className="block text-sm font-medium text-gray-700 flex justify-between items-center">
        <span>时间</span>
        {duration && (
          <span className="text-sm text-primary flex items-center gap-1 font-normal">
            <Clock size={14} />
            总时长: {duration}
          </span>
        )}
      </label>
      
      <div className="space-y-2">
        {ranges.map((range, index) => (
          <div key={index} className="flex items-center gap-2">
            <div className="relative flex-1">
              <input
                type="time"
                value={range.start}
                onChange={(e) => handleTimeChange(index, 'start', e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary text-sm"
              />
            </div>
            <span className="text-gray-500">-</span>
            <div className="relative flex-1">
              <input
                type="time"
                value={range.end}
                onChange={(e) => handleTimeChange(index, 'end', e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary text-sm"
              />
            </div>
            
            {ranges.length > 1 && (
              <button
                type="button"
                onClick={() => handleRemoveTimeRange(index)}
                className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                title="删除时间段"
              >
                <Trash2 size={16} />
              </button>
            )}
          </div>
        ))}
      </div>

      <button
        type="button"
        onClick={handleAddTimeRange}
        className="self-start text-sm text-primary hover:text-primary-hover flex items-center gap-1 mt-1"
      >
        <Plus size={14} />
        添加时间段
      </button>
    </div>
  )
}
