import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { supabase } from '../supabaseClient'
import { useAuthStore } from '../store/authStore'
import { Image, X, Upload, Save, BookOpen, PenTool } from 'lucide-react'

import { useUIStore } from '../store/uiStore'
import { useDraft } from '../hooks/useDraft'
import { TimeRangePicker, calculateDuration, TimeRange } from '../components/TimeRangePicker'
import { ConfirmDialog } from '../components/ConfirmDialog'

const ClockIn: React.FC = () => {
  // Basic State
  const [content, setContent] = useState('')
  const [category, setCategory] = useState('日常')
  const [images, setImages] = useState<string[]>([])
  const [uploading, setUploading] = useState(false)
  const [submitting, setSubmitting] = useState(false)

  // Learning Template State
  const [enableLearning, setEnableLearning] = useState(false)
  const [learningContent, setLearningContent] = useState('')
  const [learningTimeRanges, setLearningTimeRanges] = useState<TimeRange[]>([{ start: '', end: '' }])

  // Practice Template State
  const [enablePractice, setEnablePractice] = useState(false)
  const [practiceContent, setPracticeContent] = useState('')
  const [practiceTimeRanges, setPracticeTimeRanges] = useState<TimeRange[]>([{ start: '', end: '' }])
  const [practiceCount, setPracticeCount] = useState('')
  const [practiceCorrect, setPracticeCorrect] = useState('')

  // Shared Summary
  const [summary, setSummary] = useState('')

  // Dialog State
  const [confirmDialog, setConfirmDialog] = useState<{ isOpen: boolean; onConfirm: () => void }>({ isOpen: false, onConfirm: () => {} })

  const { user } = useAuthStore()
  const { addToast } = useUIStore()
  const navigate = useNavigate()

  const { 
    saveDraft, 
    clearDraft, 
    updateDraftData, 
    saving: savingDraft, 
    lastSaved 
  } = useDraft({
    pageType: 'clock-in',
    initialData: { 
      content: '', 
      category: '日常', 
      images: [],
      enableLearning: false,
      learningContent: '',
      learningTimeRanges: [{ start: '', end: '' }],
      enablePractice: false,
      practiceContent: '',
      practiceTimeRanges: [{ start: '', end: '' }],
      practiceCount: '',
      practiceCorrect: '',
      summary: ''
    },
    onRecover: (data: any) => {
      setContent(data.content || '')
      setCategory(data.category || '日常')
      setImages(data.images || [])
      setEnableLearning(data.enableLearning || false)
      setLearningContent(data.learningContent || '')
      setLearningTimeRanges(data.learningTimeRanges || [{ start: '', end: '' }])
      setEnablePractice(data.enablePractice || false)
      setPracticeContent(data.practiceContent || '')
      setPracticeTimeRanges(data.practiceTimeRanges || [{ start: '', end: '' }])
      setPracticeCount(data.practiceCount || '')
      setPracticeCorrect(data.practiceCorrect || '')
      setSummary(data.summary || '')
    },
    isEmpty: (data: any) => {
      const isBasicEmpty = (!data.content || data.content.trim() === '') && (!data.images || data.images.length === 0)
      
      // If templates are enabled, check if they have content
      if (data.enableLearning || data.enablePractice) {
        return false 
      }
      
      return isBasicEmpty
    }
  })

  useEffect(() => {
    updateDraftData({ 
      content, 
      category, 
      images,
      enableLearning,
      learningContent,
      learningTimeRanges,
      enablePractice,
      practiceContent,
      practiceTimeRanges,
      practiceCount,
      practiceCorrect,
      summary
    })
  }, [
    content, category, images,
    enableLearning, learningContent, learningTimeRanges,
    enablePractice, practiceContent, practiceTimeRanges, practiceCount, practiceCorrect,
    summary,
    updateDraftData
  ])

  // Auto-switch category logic
  useEffect(() => {
    if (enableLearning || enablePractice) {
      if (category !== '学习') {
        setCategory('学习')
      }
    }
  }, [enableLearning, enablePractice])

  const handleCategoryChange = (newCategory: string) => {
    if ((enableLearning || enablePractice) && newCategory !== '学习') {
      setConfirmDialog({
        isOpen: true,
        onConfirm: () => {
          setCategory(newCategory)
          setEnableLearning(false)
          setEnablePractice(false)
          // Also clear template data? The requirement says "Switching type will clear template data"
          setLearningContent('')
          setLearningTimeRanges([{ start: '', end: '' }])
          setPracticeContent('')
          setPracticeTimeRanges([{ start: '', end: '' }])
          setPracticeCount('')
          setPracticeCorrect('')
          setSummary('')
          setConfirmDialog(prev => ({ ...prev, isOpen: false }))
        }
      })
    } else {
      setCategory(newCategory)
    }
  }

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return

    setUploading(true)
    const files = Array.from(e.target.files)

    try {
      for (const file of files) {
        const fileExt = file.name.split('.').pop()
        const fileName = `${Math.random()}.${fileExt}`
        const filePath = `${user?.id}/${fileName}`

        const { error: uploadError } = await supabase.storage
          .from('clockin-images')
          .upload(filePath, file)

        if (uploadError) throw uploadError

        const { data } = supabase.storage
          .from('clockin-images')
          .getPublicUrl(filePath)

        setImages((prev) => [...prev, data.publicUrl])
      }
    } catch (error) {
      console.error('Error uploading image:', error)
      addToast({
        title: '上传失败',
        message: '图片上传失败，请重试',
        type: 'error'
      })
    } finally {
      setUploading(false)
      // Clear input
      e.target.value = ''
    }
  }

  const removeImage = (index: number) => {
    setImages((prev) => prev.filter((_, i) => i !== index))
  }

  // Validation Logic
  const isTimeRangesValid = (ranges: TimeRange[]) => {
    return ranges.every(r => r.start && r.end)
  }

  const isLearningValid = !enableLearning || (
    learningContent.trim() !== '' && 
    isTimeRangesValid(learningTimeRanges)
  )

  const isPracticeValid = !enablePractice || (
    practiceContent.trim() !== '' &&
    isTimeRangesValid(practiceTimeRanges) &&
    practiceCount !== '' &&
    practiceCorrect !== '' &&
    Number(practiceCount) > 0 &&
    Number(practiceCorrect) >= 0 &&
    Number(practiceCorrect) <= Number(practiceCount)
  )

  const isFormValid = (enableLearning || enablePractice) 
    ? (isLearningValid && isPracticeValid)
    : content.trim() !== ''

  const formatTimeRanges = (ranges: TimeRange[]) => {
    return ranges.map(r => `${r.start}-${r.end}`).join('，')
  }

  const generateFinalContent = () => {
    if (!enableLearning && !enablePractice) return content
    
    let result = ''
    
    if (enableLearning) {
      const duration = calculateDuration(learningTimeRanges)
      const times = formatTimeRanges(learningTimeRanges)
      result += `学习：${learningContent}\n`
      result += `时间：${times} ${duration}\n`
    }
    
    if (enablePractice) {
      if (enableLearning) result += '\n'
      const duration = calculateDuration(practiceTimeRanges)
      const times = formatTimeRanges(practiceTimeRanges)
      const count = Number(practiceCount)
      const correct = Number(practiceCorrect)
      const rate = count > 0 ? (correct / count * 100).toFixed(1) : '0.0'
      
      result += `做题：${practiceContent}\n`
      result += `时间：${times} ${duration}\n`
      result += `题量：${count}题\n`
      result += `正确：${correct}题（${rate}%）\n`
    }
    
    if (summary.trim()) {
      result += `\n总结：${summary}`
    }
    
    return result
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!isFormValid) return

    setSubmitting(true)

    const finalContent = generateFinalContent()

    try {
      const { error } = await supabase.from('clockins').insert([
        {
          user_id: user?.id,
          content: finalContent,
          category: category,
          images: images,
        },
      ])

      if (error) throw error

      // Add success toast
      addToast({
        title: '打卡成功',
        message: '您的打卡记录已成功保存',
        type: 'success'
      })

      // Add notification
      await supabase.from('notifications').insert([
        {
          user_id: user?.id,
          title: '打卡成功',
          content: `您已完成今日打卡：${finalContent.substring(0, 20)}${finalContent.length > 20 ? '...' : ''}`,
          type: 'success'
        }
      ])

      await clearDraft()

      navigate('/')
    } catch (error) {
      console.error('Error submitting clock-in:', error)
      addToast({
        title: '打卡失败',
        message: '提交过程中发生错误，请重试',
        type: 'error'
      })
    } finally {
      setSubmitting(false)
    }
  }

  const renderCorrectRate = () => {
    if (!practiceCount || !practiceCorrect) return null
    const count = Number(practiceCount)
    const correct = Number(practiceCorrect)
    if (count <= 0) return null
    const rate = (correct / count * 100).toFixed(1)
    return <span className="text-sm text-gray-500 ml-2">正确率: {rate}%</span>
  }

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          📝 每日打卡
        </h2>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Category Selection */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              打卡类型
            </label>
            <select
              value={category}
              onChange={(e) => handleCategoryChange(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary bg-white"
            >
              <option value="日常">日常</option>
              <option value="学习">学习</option>
              <option value="运动">运动</option>
              <option value="工作">工作</option>
              <option value="其他">其他</option>
            </select>
          </div>

          {/* Template Selection Toggles */}
          <div className="flex flex-wrap gap-4 p-4 bg-gray-50 rounded-lg">
            <label className="flex items-center gap-2 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={enableLearning}
                onChange={(e) => setEnableLearning(e.target.checked)}
                className="w-4 h-4 text-primary border-gray-300 rounded focus:ring-primary"
              />
              <span className="flex items-center gap-1 text-sm font-medium text-gray-700">
                <BookOpen size={16} />
                启用学习模板
              </span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={enablePractice}
                onChange={(e) => setEnablePractice(e.target.checked)}
                className="w-4 h-4 text-primary border-gray-300 rounded focus:ring-primary"
              />
              <span className="flex items-center gap-1 text-sm font-medium text-gray-700">
                <PenTool size={16} />
                启用做题模板
              </span>
            </label>
          </div>

          {/* Default Content Input (Only show if no templates enabled) */}
          {!enableLearning && !enablePractice && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                打卡内容
              </label>
              <textarea
                value={content}
                onChange={(e) => setContent(e.target.value)}
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary h-40 resize-none"
                placeholder="今天学习了什么？有什么收获？"
                required={!enableLearning && !enablePractice}
              />
            </div>
          )}

          {/* Learning Template Fields */}
          {enableLearning && (
            <div className="border border-blue-100 rounded-lg p-4 bg-blue-50/30 space-y-4">
              <h3 className="font-semibold text-blue-800 flex items-center gap-2 border-b border-blue-100 pb-2">
                <BookOpen size={18} />
                学习记录
              </h3>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  学习内容 <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  value={learningContent}
                  onChange={(e) => setLearningContent(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                  placeholder="例如：经济类知识点复习"
                  maxLength={200}
                />
              </div>

              <TimeRangePicker
                ranges={learningTimeRanges}
                onChange={setLearningTimeRanges}
              />
            </div>
          )}

          {/* Practice Template Fields */}
          {enablePractice && (
            <div className="border border-purple-100 rounded-lg p-4 bg-purple-50/30 space-y-4">
              <h3 className="font-semibold text-purple-800 flex items-center gap-2 border-b border-purple-100 pb-2">
                <PenTool size={18} />
                做题记录
              </h3>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  做题内容 <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  value={practiceContent}
                  onChange={(e) => setPracticeContent(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                  placeholder="例如：数量关系专项练习"
                  maxLength={200}
                />
              </div>

              <TimeRangePicker
                ranges={practiceTimeRanges}
                onChange={setPracticeTimeRanges}
              />

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    题量 <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="number"
                    min="1"
                    max="999"
                    value={practiceCount}
                    onChange={(e) => setPracticeCount(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                    placeholder="1-999"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    正确数 <span className="text-red-500">*</span>
                  </label>
                  <div className="relative">
                    <input
                      type="number"
                      min="0"
                      max={practiceCount}
                      value={practiceCorrect}
                      onChange={(e) => setPracticeCorrect(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
                      placeholder="0-题量"
                    />
                  </div>
                  {renderCorrectRate()}
                </div>
              </div>
            </div>
          )}

          {/* Shared Summary */}
          {(enableLearning || enablePractice) && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                总结 (选填)
              </label>
              <textarea
                value={summary}
                onChange={(e) => setSummary(e.target.value)}
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary h-32 resize-none"
                placeholder="记录一下今天的学习心得吧..."
                maxLength={500}
              />
            </div>
          )}

          {/* Image Upload */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              上传图片
            </label>
            <div className="grid grid-cols-3 gap-4 mb-4">
              {images.map((img, index) => (
                <div key={index} className="relative group aspect-square">
                  <img
                    src={img}
                    alt={`Uploaded ${index + 1}`}
                    className="w-full h-full object-cover rounded-lg"
                  />
                  <button
                    type="button"
                    onClick={() => removeImage(index)}
                    className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <X size={16} />
                  </button>
                </div>
              ))}
              
              <label className="border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center cursor-pointer hover:border-primary hover:text-primary transition-colors aspect-square">
                <input
                  type="file"
                  multiple
                  accept="image/*"
                  onChange={handleImageUpload}
                  className="hidden"
                  disabled={uploading}
                />
                {uploading ? (
                  <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-gray-400"></div>
                ) : (
                  <>
                    <Upload size={24} className="mb-2" />
                    <span className="text-sm">上传图片</span>
                  </>
                )}
              </label>
            </div>
          </div>

          <div className="flex justify-end gap-4 items-center">
            {lastSaved && (
              <span className="text-sm text-gray-500">
                {savingDraft ? '保存中...' : `上次保存: ${lastSaved.toLocaleTimeString()}`}
              </span>
            )}
            
            <button
              type="button"
              onClick={() => saveDraft({ 
                content, category, images,
                enableLearning, learningContent, learningTimeRanges,
                enablePractice, practiceContent, practiceTimeRanges, practiceCount, practiceCorrect,
                summary
              }, true)}
              disabled={savingDraft || !isFormValid}
              className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors flex items-center gap-2 disabled:opacity-50"
            >
              <Save size={18} />
              保存草稿
            </button>

            <button
              type="submit"
              disabled={submitting || !isFormValid}
              className="bg-primary text-white px-8 py-2 rounded-lg hover:bg-primary-hover transition-colors disabled:bg-gray-300 flex items-center gap-2"
            >
              {submitting ? '提交中...' : '发布打卡'}
            </button>
          </div>
        </form>
      </div>

      <ConfirmDialog
        isOpen={confirmDialog.isOpen}
        title="切换类型确认"
        message="切换类型将清空当前模板填写的数据，是否继续？"
        confirmText="确认切换"
        cancelText="取消"
        onConfirm={confirmDialog.onConfirm}
        onCancel={() => setConfirmDialog({ isOpen: false, onConfirm: () => {} })}
        type="warning"
      />
    </div>
  )
}

export default ClockIn
